+    ], $host);
+    must_ok($key, 'create key');
+
+    return ['projectId' => $pid, 'apiKey' => $key['body']['secret']];
+}
+
+$projectId = getenv('PROJECT_ID') ?: '';
+$apiKey = getenv('API_KEY') ?: '';
+if ($projectId === '' || $apiKey === '') {
