+			return 'merged';
+		case Codicon.gitPullRequestClosed.id:
+			return 'closed';
+		case Codicon.gitPullRequestDraft.id:
+			return 'draft';
+		case Codicon.gitPullRequest.id:
+		case Codicon.gitPullRequestError.id:
+		case Codicon.gitPullRequestComment.id:
+			return 'open';
+		default:
+			return undefined;
